"""A clump of woodland ferns (generated by npm run new): long arching fronds rising from one crown and bending outwards,
each a tapering midrib with alternating leaflet cards that shrink towards the tip, dark inside and underneath, lit
yellow-green on the outer, upper fronds. Variants: an upright clump and a lower, flatter, spreading one."""
import math
import random

from propsmith import prop
from propsmith.materials import material
from propsmith.shapes import blob, box

# Overall dimensions (metres), from the description.
CLUMP_REACH = 0.33 # horizontal reach of the longest midrib, upright clump (about 0.7 m across with leaflets)
CLUMP_H = 0.42  # peak height of the tallest midrib, upright clump (about 0.45 m with leaflets)
LOW_REACH = 0.39 # spreading clump, about 0.8 m across
LOW_H = 0.26  # spreading clump, about 0.3 m high
CROWN_R = 0.06  # radius of the root crown
CROWN_Z = 0.03  # height the fronds rise from
LEAF_MAX = 0.12  # length of the longest leaflet, near the base of a frond
LEAF_T = 0.004  # leaf card thickness
RIB_W = 0.005  # midrib thickness
SEGMENTS = 6  # midrib segments per frond
LEAFLETS = 17  # leaflets per frond, alternating sides
BARE = 0.15  # fraction of a frond that is bare stalk

DEEP = (0.035, 0.055, 0.018)  # linear RGB, shadow green inside and underneath
OLIVE = (0.1, 0.13, 0.035)  # mid olive
LIT = (0.21, 0.25, 0.065)  # lit yellow-green on the top and outer rims
RIB = (0.07, 0.075, 0.025)
CROWN = (0.05, 0.04, 0.02)


def _mats():
    return (
        material("fern_deep", DEEP, rough=0.85, vary=0.3, scale=30, crevice=0.6),
        material("fern_olive", OLIVE, rough=0.85, vary=0.3, scale=30, crevice=0.5),
        material("fern_lit", LIT, rough=0.85, vary=0.25, scale=30, crevice=0.4),
        material("fern_rib", RIB, rough=0.9, vary=0.2, scale=30, crevice=0.5),
    )


def _arc(e0, e1, reach, peak):
    """Midrib points: an arc whose elevation falls from e0 to e1 degrees, scaled to `reach` and `peak`."""
    pts = [(0.0, 0.0)]
    for k in range(SEGMENTS):
        s = (k + 0.5) / SEGMENTS
        e = math.radians(e0 + (e1 - e0) * s ** 1.3)
        h, z = pts[-1]
        pts.append((h + math.cos(e), z + math.sin(e)))
    hmax = max(p[0] for p in pts)
    zmax = max(p[1] for p in pts)
    return [(h * reach / hmax, z * peak / zmax) for h, z in pts]


def _point(obj, tail=0.6):
    """Reshape a leaf card box (corners at +-x, +-y) into a pointed leaf: the tip on +x, a shorter blunt end on -x
    (`tail` of the half-length), widest in the middle. Same vertices and faces, so it stays a closed mesh."""
    for v in obj.data.vertices:
        x, y = v.co.x, v.co.y
        if x > 0 and y > 0:
            v.co.x, v.co.y = x, 0.0
        elif x < 0 < y:
            v.co.x = 0.0
        elif x < 0 and y < 0:
            v.co.x, v.co.y = x * tail, 0.0
        else:
            v.co.x = 0.0
    return obj


def _frond(name, rnd, yaw, e0, e1, reach, peak, light, mats):
    deep, olive, lit, rib = mats
    arc = _arc(e0, e1, reach, peak)
    # keep the tip off the ground
    arc = [(h, max(z, 0.012 - CROWN_Z)) for h, z in arc]
    cy, sy = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
    pts = [(h * cy, h * sy, CROWN_Z + z) for h, z in arc]
    lengths = [math.dist(pts[k], pts[k + 1]) for k in range(SEGMENTS)]
    total = sum(lengths)

    def at(s):
        """Point and elevation (degrees) at fraction `s` of the midrib."""
        d = s * total
        for k in range(SEGMENTS):
            if d <= lengths[k] or k == SEGMENTS - 1:
                t = min(d / lengths[k], 1.0)
                a, b = pts[k], pts[k + 1]
                p = tuple(a[i] + (b[i] - a[i]) * t for i in range(3))
                e = math.degrees(math.atan2(arc[k + 1][1] - arc[k][1], arc[k + 1][0] - arc[k][0]))
                return p, e
            d -= lengths[k]

    for k in range(SEGMENTS):
        a, b = pts[k], pts[k + 1]
        e = math.degrees(math.atan2(arc[k + 1][1] - arc[k][1], arc[k + 1][0] - arc[k][0]))
        mid = tuple((a[i] + b[i]) / 2 for i in range(3))
        w = RIB_W * (1 - 0.5 * k / SEGMENTS)
        box(f"{name}_rib_{k}", (lengths[k] + 0.004, w, w), mid, rib, rot=(0, -e, yaw), bevel=0)

    for j in range(LEAFLETS):
        s = BARE + (0.97 - BARE) * (j + 0.5) / LEAFLETS
        p, e = at(s)
        side = 1 if j % 2 == 0 else -1
        ln = LEAF_MAX * (1 - 0.78 * (s - BARE) / (1 - BARE)) * rnd.uniform(0.85, 1.1) * (reach / CLUMP_REACH) ** 0.5
        wd = max(ln * 0.5, 0.014)
        sweep = rnd.uniform(25, 40)  # leaflets lean towards the tip
        ly = yaw + side * (90 - sweep)
        pitch = 0.35 * e - rnd.uniform(8, 22)  # droop below the midrib
        roll = side * rnd.uniform(-15, 25)
        cp, sp = math.cos(math.radians(pitch)), math.sin(math.radians(pitch))
        dx, dy = math.cos(math.radians(ly)) * cp, math.sin(math.radians(ly)) * cp
        c = (p[0] + dx * ln / 2, p[1] + dy * ln / 2, p[2] + sp * ln / 2)
        low = c[2] - abs(sp) * ln / 2 - wd / 2 * abs(math.sin(math.radians(roll))) - LEAF_T
        if low < 0.002:
            c = (c[0], c[1], c[2] + 0.002 - low)
        score = 0.45 * s + 0.45 * light + rnd.uniform(-0.15, 0.15)
        if c[2] < 0.08:
            score -= 0.2  # underneath
        mat = deep if score < 0.38 else olive if score < 0.68 else lit
        _point(box(f"{name}_leaf_{j}", (ln, wd, LEAF_T), c, mat, rot=(roll, -pitch, ly), bevel=0), tail=0.3)


def _crown(rnd, mats, seed):
    deep = mats[0]
    blob("fern_crown", CROWN_R, (0, 0, CROWN_R * 0.5), material("fern_crown", CROWN, vary=0.2, scale=20),
         squash=(1, 1, 0.5), subdiv=1, seed=seed, jitter=0.15)
    # a few short dark cards hiding the crown
    for i in range(6):
        yaw = 60 * i + rnd.uniform(-15, 15)
        tilt = rnd.uniform(15, 30)
        r = CROWN_R * 0.9
        c = (r * math.cos(math.radians(yaw)), r * math.sin(math.radians(yaw)), 0.03)
        box(f"fern_core_{i}", (0.07, 0.03, LEAF_T), c, deep, rot=(rnd.uniform(-10, 10), -tilt, yaw), bevel=0)


def _clump(rnd, n, reach, peak, e0, e1, flat):
    mats = _mats()
    _crown(rnd, mats, rnd.randint(0, 99))
    for i in range(n):
        yaw = 360 * i / n + rnd.uniform(-12, 12)
        inner = i % 2 == 0
        if inner:  # upright, shorter, the highest fronds
            fr = rnd.uniform(0.75, 0.9)
            fp = rnd.uniform(0.85, 1.0)
            a0, a1 = e0 + rnd.uniform(0, 8), e1 + rnd.uniform(0, 10)
        else:  # outer, longer, lower and flatter
            fr = rnd.uniform(0.88, 1.0)
            fp = rnd.uniform(0.6, 0.75) * (1 - 0.15 * flat)
            a0, a1 = e0 - rnd.uniform(10, 18), e1 - rnd.uniform(0, 12)
        light = (0.65 if inner else 0.45) + rnd.uniform(-0.25, 0.3)
        _frond(f"fern_frond_{i}", rnd, yaw, a0, a1, reach * fr, peak * fp, light, mats)


@prop
def fern_clump():
    rnd = random.Random(17)
    _clump(rnd, 11, CLUMP_REACH, CLUMP_H, 75, -45, flat=0)


@prop
def fern_clump_low():
    rnd = random.Random(29)
    _clump(rnd, 12, LOW_REACH, LOW_H, 48, -25, flat=1)
